```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wasi::clocks::wall_clock::now();
        let secs = now.seconds;
        RunInfo {
            date: format_utc_date(secs),
            started: secs,
        }
    }
}

/// Formats seconds since the Unix epoch as a UTC calendar date, `YYYY-MM-DD`.
/// Uses the civil-from-days algorithm (Howard Hinnant), with no dependencies.
fn format_utc_date(epoch_secs: u64) -> String {
    let z: i64 = (epoch_secs / 86_400) as i64 + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    format!("{:04}-{:02}-{:02}", y, m, d)
}

export!(Node);
